function calculatePrice(order) {
  if (order.isPriority && order.total > 1000) {
    return order.total * 0.9;
  } else if (order.customer.isVip) {
    return order.total * 0.85;
  } else if (order.items.length > 10) {
    return order.total * 0.95;
  }
  return order.total;
}

function approveLoan(applicant) {
  if (applicant.creditScore > 700 && applicant.income > 50000) {
    return 'approved';
  }
  if (applicant.creditScore > 600 && applicant.employmentYears > 2) {
    return 'manual-review';
  }
  return 'declined';
}

// Version A
function computeFee(order) {
  if (order.type === 'standard' && order.weight < 5) {
    return 5;
  }
  if (order.type === 'standard' && order.weight >= 5) {
    return 10 + order.weight * 0.5;
  }
  if (order.type === 'express') {
    if (order.destination === 'local') return 20;
    return 50;
  }
  return 0;
}

// Version B
function computeFee(order) {
  if (isStandardLight(order)) return standardLightFee(order);
  if (isStandardHeavy(order)) return standardHeavyFee(order);
  if (isExpress(order)) return expressFee(order);
  return 0;
}

function isStandardLight(o){ return o.type === 'standard' && o.weight < 5; }
function standardLightFee(o){ return 5; }
function isStandardHeavy(o){ return o.type === 'standard' && o.weight >= 5; }
function standardHeavyFee(o){ return 10 + o.weight * 0.5; }
function isExpress(o){ return o.type === 'express'; }
function expressFee(o){ return o.destination === 'local' ? 20 : 50; }
